 export function joinCoverage(document: ReviewDocument, live: LiveHunk[]): ReviewCoverage {
   const liveByKey = new Map<string, LiveHunk>();
+  const liveByPath = new Map<string, LiveHunk[]>();
   for (const hunk of live) {
